def hexrgb(h):
    h=h.lstrip('#'); return [int(h[i:i+2],16)/255 for i in (0,2,4)] + [1]
def prop(v): return {"a":0,"k":v}
def kf(v0,v1,v2=None):
    if v2 is None: v2=v0
    def key_value(v): return v if isinstance(v,(list,tuple)) else [v]
    e={"i":{"x":[0.42],"y":[0]},"o":{"x":[0.58],"y":[1]}}
    return {"a":1,"k":[{"t":0,"s":key_value(v0),"e":key_value(v1),**e},{"t":30,"s":key_value(v1),"e":key_value(v2),**e},{"t":60,"s":key_value(v2),"e":key_value(v0),**e}]}
def transform(x,y,scale,rot):
    return {"ty":"tr","o":prop(100),"r":kf(rot-5,rot+5,rot-5),"p":kf([x,y,0],[x+2,y-3,0],[x,y,0]),"a":prop([0,0,0]),"s":kf([scale-3,scale-3,100],[scale+3,scale+3,100],[scale-3,scale-3,100])}
def fill(c,o=100): return {"ty":"fl","c":prop(hexrgb(c)),"o":prop(o),"r":1,"bm":0}
def stroke(c,w=5): return {"ty":"st","c":prop(hexrgb(c)),"o":prop(100),"w":prop(w),"lc":2,"lj":2,"bm":0}
def ellipse(name,sx,sy,c,outline=None,w=4):
    a=[{"ty":"el","p":prop([0,0]),"s":prop([sx,sy]),"nm":name,"d":1},fill(c)]
    if outline: a += [stroke(outline,w)]
    return a
def rect(name,sx,sy,c,outline=None,r=12,w=4):
    a=[{"ty":"rc","p":prop([0,0]),"s":prop([sx,sy]),"r":prop(r),"nm":name,"d":1},fill(c)]
    if outline: a += [stroke(outline,w)]
    return a
def star(name,points,outer,inner,c,outline=None):
    a=[{"ty":"sr","sy":1,"pt":prop(points),"p":prop([0,0]),"r":prop(0),"or":prop(outer),"ir":prop(inner),"is":prop(0),"os":prop(0),"nm":name,"d":1},fill(c)]
    if outline: a += [stroke(outline,4)]
    return a
def path(name,verts,c=None,outline=None,w=5,closed=True):
    tang=[[0,0] for _ in verts]; a=[{"ty":"sh","ks":prop({"i":tang,"o":tang,"v":verts,"c":closed}),"nm":name,"d":1}]
    if c: a += [fill(c)]
    if outline: a += [stroke(outline,w)]
    return a
def group(name,items,x,y,scale=100,rot=0): return {"ty":"gr","it":items+[transform(x,y,scale,rot)],"nm":name,"np":len(items)+1,"bm":0}

